const API='/api';
const state={token:localStorage.getItem('stq_token')||'',user:null,view:'dashboard',appointments:[],branches:[],queue:[],notifications:[],complaints:[],dashboard:null,search:'',filter:'all',selectedAppointment:null,language:localStorage.getItem('stq_lang')||'English'};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10); const prettyDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const initials=n=>(n||'U').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const roleName=r=>({citizen:'Citizen',staff:'Staff',admin:'Administrator'}[r]||r);
const statusLabel=s=>(s||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const res=await fetch(API+path,{...opts,headers});const data=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401&&state.token){logout(false);throw new Error(data.error||'Please sign in again.')}throw new Error(data.error||'Request failed.')}return data;}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+(type==='error'?'error':'');el.innerHTML=`<span>${type==='error'?'!':'✓'}</span>${escapeHTML(msg)}`;$('#toast-root').append(el);setTimeout(()=>el.remove(),3800)}
function logout(show=true){state.token='';state.user=null;localStorage.removeItem('stq_token');if(show)toast('You have been signed out.');renderLogin();}
function renderLogin(){document.body.className='';$('#app').innerHTML=`<section class="login-shell"><div class="login-brand"><div class="brand-mark">S<span>Q</span></div><span>SkipTheQueue</span></div><div class="login-copy"><div class="eyebrow"><span class="pulse"></span> THE SMARTER WAY TO WAIT</div><h1>Your time is<br><em>yours again.</em></h1><p>Book ahead. Track your place. Walk in when it’s your turn — not before.</p><div class="login-points"><div><span class="point-icon">↗</span><span><b>Know before you go</b><small>Live queue visibility & smart estimates</small></span></div><div><span class="point-icon">◷</span><span><b>Make every minute count</b><small>Easy appointments, no crowded waiting rooms</small></span></div></div><div class="login-art"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="art-card"><div class="art-card-top"><span class="mini-dot"></span> YOUR QUEUE PASS <span class="live-pill">LIVE</span></div><div class="art-token">A<span>·</span>024</div><div class="art-progress"><span></span></div><div class="art-bottom"><span><small>PEOPLE AHEAD</small><b>02</b></span><span><small>EST. WAIT</small><b>~ 8 min</b></span><span class="qr-mini">▦</span></div></div><div class="floating-note"><span>✓</span> Appointment confirmed</div></div><div class="login-footer">Built around people, not queues. <span>© SkipTheQueue 2026</span></div></div><div class="login-panel"><div class="login-panel-inner"><div class="mobile-brand"><div class="brand-mark">S<span>Q</span></div><b>SkipTheQueue</b></div><div class="login-heading"><span class="eyebrow">WELCOME BACK</span><h2>Good to see you.</h2><p>Sign in to your personal queue dashboard.</p></div><div class="auth-tabs"><button class="auth-tab active" data-auth-tab="login">Sign in</button><button class="auth-tab" data-auth-tab="register">Create account</button></div><form id="login-form" class="auth-form"><label>Email address<input type="email" name="email" placeholder="you@example.com" value="citizen@skipthequeue.demo" required></label><label>Password<div class="password-wrap"><input type="password" name="password" placeholder="Enter your password" value="Queue@123" required><button type="button" class="show-password" aria-label="Show password">◉</button></div></label><div class="form-row"><label class="check-label"><input type="checkbox" checked> Keep me signed in</label><span class="hint">Demo environment</span></div><button class="btn btn-primary btn-full" type="submit">Sign in <span>→</span></button><div class="auth-error" id="auth-error"></div><div class="demo-access"><div class="demo-title"><span>✦</span> Explore a demo role</div><div class="demo-buttons"><button type="button" data-demo="citizen">Citizen</button><button type="button" data-demo="staff">Staff</button><button type="button" data-demo="admin">Admin</button></div><small>Demo password for all roles: <b>Queue@123</b></small></div></form><form id="register-form" class="auth-form hidden"><label>Full name<input name="name" placeholder="Your full name" required></label><label>Email address<input type="email" name="email" placeholder="you@example.com" required></label><label>Password<input type="password" name="password" minlength="8" placeholder="At least 8 characters" required></label><label>Phone (optional)<input name="phone" inputmode="tel" placeholder="Mobile number"></label><button class="btn btn-primary btn-full" type="submit">Create my account <span>→</span></button><div class="auth-error" id="register-error"></div><p class="terms-note">By creating an account, you agree to use the demo responsibly.</p></form><div class="login-privacy"><span>♧</span> Your data is protected with secure sign-in.</div></div></div></section>`;bindLogin();}
function bindLogin(){ $$('[data-auth-tab]').forEach(b=>b.onclick=()=>{ $$('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#login-form').classList.toggle('hidden',b.dataset.authTab!=='login');$('#register-form').classList.toggle('hidden',b.dataset.authTab!=='register');});const pw=$('.show-password');pw.onclick=()=>{const input=pw.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';};$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});state.token=d.token;state.user=d.user;localStorage.setItem('stq_token',d.token);await startApp();}catch(err){$('#auth-error').textContent=err.message;}};$('#register-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify({name:f.get('name'),email:f.get('email'),password:f.get('password'),phone:f.get('phone')})});state.token=d.token;state.user=d.user;localStorage.setItem('stq_token',d.token);await startApp();}catch(err){$('#register-error').textContent=err.message;}};$$('[data-demo]').forEach(b=>b.onclick=()=>{const role=b.dataset.demo;const email={citizen:'citizen@skipthequeue.demo',staff:'staff@skipthequeue.demo',admin:'admin@skipthequeue.demo'}[role];$('#login-form [name=email]').value=email;$('#login-form [name=password]').value='Queue@123';$('#login-form').requestSubmit();});}
const navItems=[['dashboard','▦','Overview',['citizen','staff','admin']],['livequeue','◉','Live queue',['citizen','staff','admin']],['book','＋','Book appointment',['citizen']],['appointments','▤','My appointments',['citizen']],['queue','≋','Queue management',['staff','admin']],['branches','⌖','Branches',['citizen','staff','admin']],['notifications','♧','Notifications',['citizen','staff','admin']],['feedback','☆','Feedback',['citizen','staff','admin']],['complaints','✉','Help & complaints',['citizen','staff','admin']],['users','♙','User management',['admin']],['reports','▥','Forecast & audit',['admin']]];
async function startApp(){try{if(!state.user){const d=await api('/me');state.user=d.user;}await loadData();renderShell();renderView();}catch(e){logout(false);}}
async function loadData(){const tasks=[fetch('/api/public/branches',{cache:'no-store'}).then(r=>r.json()).then(d=>state.branches=d.branches),api('/appointments').then(d=>state.appointments=d.appointments),api('/notifications').then(d=>state.notifications=d.notifications),api('/complaints').then(d=>state.complaints=d.complaints)];if(['staff','admin'].includes(state.user.role)){tasks.push(api('/queue').then(d=>state.queue=d.queue),api('/dashboard').then(d=>state.dashboard=d));}await Promise.all(tasks);}
function renderShell(){const role=state.user.role;const items=navItems.filter(n=>n[3].includes(role));$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><div class="brand-mark">S<span>Q</span></div><span>SkipTheQueue</span></div><div class="side-label">WORKSPACE</div><nav class="side-nav">${items.slice(0,4).map(navHTML).join('')}</nav><div class="side-label" style="margin-top:24px">MANAGE</div><nav class="side-nav">${items.slice(4).map(navHTML).join('')}</nav><div class="nav-spacer"></div><div class="side-help"><div class="help-symbol">✳</div><b>Need a little help?</b><p>Our support team is here to make your visit easier.</p><button data-nav="complaints">Get support ↗</button></div><div class="side-user"><div class="avatar">${initials(state.user.name)}</div><div class="side-user-info"><b>${escapeHTML(state.user.name)}</b><small>${roleName(role)}</small></div><button class="logout-btn" id="logout-btn" title="Sign out">↪</button></div></aside><main class="main-area"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn mobile-menu" id="mobile-menu">☰</button><div class="breadcrumb">Workspace <span style="padding:0 7px;color:#cad3cd">/</span> <b id="breadcrumb-name">Overview</b></div></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})}</span><button class="icon-btn" id="top-notifications" title="Notifications">♧${state.notifications.some(n=>!n.read)?'<span class="notif-dot"></span>':''}</button><div class="avatar">${initials(state.user.name)}</div></div></header><div class="content" id="view-root"></div></main></div>`;$('#logout-btn').onclick=()=>logout();$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#top-notifications').onclick=()=>navigate('notifications');$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));}
function navHTML(n){return `<button class="nav-btn ${state.view===n[0]?'active':''}" data-nav="${n[0]}"><span class="nav-icon">${n[1]}</span>${n[2]}</button>`;}
function navigate(view){state.view=view;state.search='';state.filter='all';renderShell();renderView();window.scrollTo(0,0);}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function statusBadge(s){return `<span class="status ${escapeHTML(s)}">${statusLabel(s)}</span>`;}
function emptyState(icon,title,desc,action=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><b>${title}</b><p>${desc}</p>${action}</div>`;}
function renderView(){const root=$('#view-root');if(!root)return;const map={dashboard:renderDashboard,livequeue:renderLiveQueue,book:renderBooking,appointments:renderAppointments,queue:renderQueue,branches:renderBranches,notifications:renderNotifications,feedback:renderFeedback,complaints:renderComplaints,users:renderUsers,reports:renderReports};root.innerHTML=(map[state.view]||renderDashboard)();const label=navItems.find(n=>n[0]===state.view)?.[2]||'Overview';$('#breadcrumb-name').textContent=label;bindView();}
function renderDashboard(){const role=state.user.role;const mine=state.appointments.filter(a=>a.user_id===state.user.id);const active=mine.filter(a=>['booked','waiting','checked_in','serving'].includes(a.status));if(role==='citizen'){const next=active.sort((a,b)=>(a.appointment_date+a.slot).localeCompare(b.appointment_date+b.slot))[0];return `${pageHead('YOUR PERSONAL DASHBOARD',`Hello, ${escapeHTML(state.user.name.split(' ')[0])} 👋`,'A calmer way to get things done. Here’s what’s happening with your visits.',`<button class="btn btn-primary" data-action="book">＋ Book an appointment</button>`)}<section class="welcome-banner"><div class="welcome-copy"><div class="welcome-tag">YOUR DAY, MADE SIMPLER</div><h2>${next?'Your next visit is in the diary.':'Ready when you are.'}</h2><p>${next?`${escapeHTML(next.service)} · ${prettyDate(next.appointment_date)} at ${escapeHTML(next.slot)}.`:'Book a slot before you travel and spend less time waiting.'}</p></div><div class="welcome-right"><div class="welcome-stats"><small>ACTIVE APPOINTMENTS</small><b>${active.length.toString().padStart(2,'0')}</b></div></div></section><div class="stat-grid">${statCard('Upcoming visits',active.length,'◷','Your booked or active visits')}${statCard('Completed visits',mine.filter(a=>a.status==='completed').length,'✓','Appointments finished')}${statCard('Branches nearby',state.branches.length,'⌖','Service centres available')}${statCard('Unread updates',state.notifications.filter(n=>!n.read).length,'♧','Queue and booking updates')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Your appointments</div><div class="panel-subtitle">A quick look at your upcoming visits</div></div><button class="panel-link" data-nav="appointments">View all ↗</button></div>${active.length?`<div class="queue-preview">${active.slice(0,3).map(a=>`<div class="queue-item"><div class="queue-token">${escapeHTML(a.token)}</div><div class="queue-meta"><b>${escapeHTML(a.service)}</b><small>${escapeHTML(a.branch_name)} · ${prettyDate(a.appointment_date)} · ${escapeHTML(a.slot)}</small></div>${statusBadge(a.status)}</div>`).join('')}</div>`:emptyState('◷','No upcoming visits yet','Book a time that works for you.','<button class="btn btn-primary btn-small" data-action="book">Book a visit →</button>')}</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Quick actions</div><div class="panel-subtitle">The essentials, one tap away</div></div></div><div class="quick-actions"><button class="quick-action" data-action="book"><span>＋</span><b>Book a visit</b><small>Choose a service & time</small></button><button class="quick-action" data-nav="branches"><span>⌖</span><b>Find a branch</b><small>Compare queue levels</small></button><button class="quick-action" data-nav="notifications"><span>♧</span><b>Notifications</b><small>Stay in the loop</small></button><button class="quick-action" data-nav="complaints"><span>✳</span><b>Get support</b><small>We’re here to help</small></button></div></section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Find your service centre</div><div class="panel-subtitle">Choose a location that suits you</div></div><button class="panel-link" data-nav="branches">All branches ↗</button></div><div class="branch-list">${state.branches.slice(0,3).map(branchRow).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Helpful reminders</div><div class="panel-subtitle">A little preparation goes a long way</div></div></div><div class="branch-list"><div class="branch-row"><div class="branch-symbol">▣</div><div class="branch-details"><b>Keep your token handy</b><small>Show your booking token at check-in.</small></div></div><div class="branch-row"><div class="branch-symbol">◷</div><div class="branch-details"><b>Arrive close to your slot</b><small>We recommend arriving 5–10 minutes early.</small></div></div><div class="branch-row"><div class="branch-symbol">✧</div><div class="branch-details"><b>Bring required documents</b><small>Check your service notes before leaving.</small></div></div></div></section></div>`;}
 const d=state.dashboard||{totals:{},branch:[],week:[],ratings:{}};const t=d.totals||{};const todayQueue=(state.queue||[]).slice(0,4);return `${pageHead(role==='admin'?'ADMINISTRATION OVERVIEW':'SERVICE OPERATIONS',role==='admin'?'Your service network, at a glance':'Good day, '+escapeHTML(state.user.name.split(' ')[0]),'Monitor demand, manage today’s queue and keep every visit moving.',`<button class="btn btn-light" data-action="export">↓ Export report</button><button class="btn btn-primary" data-nav="queue">Open live queue →</button>`)}<section class="welcome-banner"><div class="welcome-copy"><div class="welcome-tag">${role==='admin'?'NETWORK HEALTH':'TODAY’S OPERATIONS'}</div><h2>Small waits. Better experiences.</h2><p>Here’s your snapshot for ${prettyDate(today())}. Queue estimates update as appointments change.</p></div><div class="welcome-right"><div class="welcome-stats"><small>AVG. SERVICE ESTIMATE</small><b>${t.avg_minutes||'—'} <span style="font-size:12px">min</span></b></div></div></section><div class="stat-grid">${statCard('Appointments today',t.total||0,'▤','All statuses included')}${statCard('Waiting in queue',t.waiting||0,'≋','Waiting or checked in')}${statCard('Currently serving',t.serving||0,'↗','In service right now')}${statCard('Completed today',t.completed||0,'✓','Finished appointments')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Appointment demand</div><div class="panel-subtitle">Bookings over the last 7 days · sample-based forecast</div></div><span class="pill"><i></i> Recent activity</span></div>${renderDemandChart(d.week||[])}</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Live queue</div><div class="panel-subtitle">Today’s next appointments</div></div><button class="panel-link" data-nav="queue">Manage ↗</button></div><div class="queue-preview">${todayQueue.length?todayQueue.map(a=>`<div class="queue-item"><div class="queue-token">${escapeHTML(a.token)}</div><div class="queue-meta"><b>${escapeHTML(a.user_name)} · ${escapeHTML(a.service)}</b><small>${escapeHTML(a.branch_name)} · ${escapeHTML(a.slot)}</small></div>${statusBadge(a.status)}</div>`).join(''):emptyState('≋','Queue is clear','No active appointments for today.')}</div></section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Branch activity</div><div class="panel-subtitle">Bookings across the last seven days</div></div><button class="panel-link" data-nav="branches">View branches ↗</button></div><div class="branch-list">${(d.branch||[]).map(b=>`<div class="branch-row"><div class="branch-symbol">⌖</div><div class="branch-details"><b>${escapeHTML(b.name)}</b><small>Recent appointment volume</small></div><span class="branch-queue">${b.bookings} bookings</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Operations shortcuts</div><div class="panel-subtitle">Move from insight to action</div></div></div><div class="quick-actions"><button class="quick-action" data-nav="queue"><span>≋</span><b>Manage queue</b><small>Call and update tokens</small></button><button class="quick-action" data-action="export"><span>↓</span><b>Export report</b><small>Download appointment CSV</small></button><button class="quick-action" data-nav="complaints"><span>✉</span><b>Support tickets</b><small>Review incoming issues</small></button><button class="quick-action" data-nav="feedback"><span>☆</span><b>Feedback</b><small>Review citizen experience</small></button></div></section></div>`;}
function statCard(title,value,icon,foot){return `<div class="stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function branchRow(b){return `<div class="branch-row"><div class="branch-symbol">⌖</div><div class="branch-details"><b>${escapeHTML(b.name)}</b><small>${escapeHTML(b.address)}, ${escapeHTML(b.city)}</small></div><span class="branch-queue">${b.active_queue||0} <span style="font-weight:500;color:#8fa096">in queue</span></span></div>`;}
function renderDemandChart(rows){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const iso=d.toISOString().slice(0,10);days.push({day:iso,count:(rows.find(r=>r.day===iso)||{}).count||0,label:d.toLocaleDateString('en-IN',{weekday:'short'})});}const max=Math.max(1,...days.map(d=>d.count));return `<div class="chart-wrap"><div class="bar-chart">${days.map((d,i)=>`<div class="bar-group"><div class="bar-stack"><div class="bar" title="${d.count} appointments" style="height:${Math.max(4,d.count/max*100)}%"></div></div><div class="bar-label">${d.label}</div></div>`).join('')}</div></div><div class="chart-legend"><span><i class="legend-dot dark"></i>Appointments booked</span><span><i class="legend-dot"></i>Recent activity</span><span style="margin-left:auto">${rows.reduce((s,r)=>s+r.count,0)} total in data</span></div>`;}
function renderBooking(){const role=state.user.role;if(role!=='citizen')return renderBranches();return `${pageHead('PLAN AHEAD','Book an appointment','Choose your branch, service and a time that fits your day.')}<div class="booking-layout"><section class="panel form-panel"><form id="booking-form"><div class="form-grid"><div class="form-field full"><label for="branch_id">Service centre</label><select id="branch_id" name="branch_id" required><option value="">Choose a branch</option>${state.branches.map(b=>`<option value="${b.id}">${escapeHTML(b.name)} — ${escapeHTML(b.city)} · ${b.active_queue||0} in queue</option>`).join('')}</select><div class="field-help">Compare active queue counts to help choose a quieter location.</div></div><div class="form-field full"><label for="service">What do you need help with?</label><select id="service" name="service" required><option value="">Select a service</option><option>Document verification</option><option>Certificate application</option><option>Address update</option><option>General enquiry</option><option>Payment or fee assistance</option><option>Other service</option></select></div><div class="form-field"><label for="appointment_date">Preferred date</label><input type="date" id="appointment_date" name="appointment_date" min="${today()}" value="${today()}" required></div><div class="form-field"><label for="slot">Available time slot</label><select id="slot" name="slot" required>${['09:00','09:15','09:30','09:45','10:00','10:15','10:30','10:45','11:00','11:15','11:30','11:45','12:00','12:15','12:30','12:45','13:00','13:15','13:30','13:45','14:00','14:15','14:30','14:45','15:00','15:15','15:30','15:45','16:00','16:15','16:30','16:45'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="form-field"><label for="priority">Priority assistance</label><select id="priority" name="priority"><option value="normal">Standard</option><option value="senior">Senior citizen</option><option value="disability">Accessibility support</option></select><div class="field-help">Priority options are for eligible visitors who need assistance.</div></div><div class="form-field"><label for="language">Preferred language</label><select id="language" name="language"><option>English</option><option>हिन्दी</option><option>मराठी</option></select></div><div class="form-field full"><label for="notes">Notes for the service team (optional)</label><textarea id="notes" name="notes" maxlength="500" placeholder="Any details that will help us prepare for your visit..."></textarea></div></div><div class="form-actions"><button class="btn btn-light" type="reset">Clear form</button><button class="btn btn-primary" type="submit">Confirm appointment <span>→</span></button></div></form></section><aside class="booking-aside"><div class="aside-icon">✳</div><h3>Skip the wait.<br>Keep your day.</h3><p>Your appointment includes a unique token and an estimated service time. We’ll keep you updated as your visit approaches.</p><div class="aside-tip"><b>✦ Smart time estimate</b><br>Estimates consider the service type, earlier bookings and typical busy periods. Actual wait time may vary.</div><div class="aside-tip"><b>▣ On the day</b><br>Arrive 5–10 minutes early and bring any documents listed for your service.</div></aside></div>`;}
function renderAppointments(){const citizen=state.user.role==='citizen';let list=citizen?state.appointments.filter(a=>a.user_id===state.user.id):state.appointments;list=list.filter(a=>(state.filter==='all'||a.status===state.filter)&&[a.service,a.token,a.branch_name,a.status].join(' ').toLowerCase().includes(state.search.toLowerCase()));return `${pageHead(citizen?'YOUR VISIT HISTORY':'APPOINTMENT REGISTER',citizen?'My appointments':'All appointments',citizen?'Manage upcoming visits and keep track of completed services.':'Search, review and update appointment records.',citizen?'<button class="btn btn-primary" data-action="book">＋ Book appointment</button>':'<button class="btn btn-light" data-action="export">↓ Export CSV</button>')}<section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">${citizen?'Your visits':'Appointment records'}</div><div class="panel-subtitle">${list.length} record${list.length===1?'':'s'} found</div></div><div class="table-tools"><input class="search-input" id="table-search" placeholder="Search token, service…" value="${escapeHTML(state.search)}"><select class="filter-select" id="status-filter"><option value="all">All statuses</option>${['booked','waiting','checked_in','serving','completed','cancelled','no_show'].map(s=>`<option value="${s}" ${state.filter===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr><th>TOKEN</th>${citizen?'':'<th>CITIZEN</th>'}<th>SERVICE & BRANCH</th><th>DATE & TIME</th><th>STATUS</th><th>QUEUE / COUNTER</th><th>PREDICTED WAIT</th><th>EST. TIME</th><th>ACTION</th></tr></thead><tbody>${list.length?list.map(a=>`<tr><td class="token-cell">${escapeHTML(a.token)}</td>${citizen?'':`<td><b>${escapeHTML(a.user_name)}</b><br><span style="font-size:9px;color:#9aa79f">${escapeHTML(a.user_email||'')}</span></td>`}<td><b>${escapeHTML(a.service)}</b><br><span style="font-size:9px;color:#98a69d">${escapeHTML(a.branch_name)}</span></td><td>${prettyDate(a.appointment_date)}<br><span style="font-size:9px;color:#98a69d">${escapeHTML(a.slot)}</span></td><td>${statusBadge(a.status)}</td><td>${a.queue_position?`#${a.queue_position}${a.counter_name?' · '+escapeHTML(a.counter_name):''}`:'—'}</td><td>${['booked','waiting','checked_in','serving'].includes(a.status)?`${a.estimated_wait_minutes||0} min <span class=\"hint\">predicted</span>`:'—'}</td><td>${a.estimated_minutes} min</td><td>${citizen&&['booked','waiting'].includes(a.status)?`<button class="table-action" data-reschedule="${a.id}">Reschedule</button> <button class="table-action" data-cancel="${a.id}">Cancel</button>`:state.user.role!=='citizen'&&['booked','waiting','checked_in','serving'].includes(a.status)?`<button class="table-action" data-appointment-status="${a.id}" data-next-status="${a.status==='booked'?'checked_in':a.status==='checked_in'?'serving':a.status==='serving'?'completed':'checked_in'}">${a.status==='booked'?'Check in':a.status==='checked_in'?'Start service':a.status==='serving'?'Complete':'Check in'}</button>`:'—'}</td></tr>`).join(''):`<tr><td colspan="9" class="table-empty">No appointments match your search.</td></tr>`}</tbody></table></div></section>`;}
function renderQueue(){if(state.user.role==='citizen')return renderAppointments();const list=state.queue.filter(a=>(state.filter==='all'||a.status===state.filter)&&[a.user_name,a.service,a.token,a.branch_name].join(' ').toLowerCase().includes(state.search.toLowerCase()));return `${pageHead('FRONT DESK','Queue management','Keep the line moving with clear, consistent status updates.',`<button class="btn btn-light" data-action="refresh">↻ Refresh queue</button><button class="btn btn-primary" data-action="export">↓ Export</button>`)}<section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><div class="panel-title">Check in / call next</div><div class="panel-subtitle">Enter the decoded QR token manually, or use the appointment token printed on the pass.</div></div><button class="btn btn-primary" data-action="call-next">Call next eligible customer →</button></div><form id="quick-checkin-form" class="form-grid" style="align-items:end"><div class="form-field"><label>Appointment token</label><input name="token" placeholder="e.g. STQ-AB12" required></div><div class="form-field"><label>Branch</label><select name="branch_id" required>${state.branches.map(b=>`<option value="${b.id}">${escapeHTML(b.name)}</option>`).join('')}</select></div><div class="form-field"><label>Counter ID (optional)</label><input name="counter_id" type="number" min="1" placeholder="Counter ID"></div><div class="form-field"><button class="btn btn-light" type="submit">Check in token</button></div></form></section><div class="stat-grid">${statCard('Active tokens',state.queue.length,'≋','Booked, waiting or in service')}${statCard('Waiting',state.queue.filter(a=>['waiting','checked_in','booked'].includes(a.status)).length,'◷','Awaiting their turn')}${statCard('Priority visitors',state.queue.filter(a=>a.priority!=='normal').length,'✧','Priority assistance flagged')}${statCard('Serving now',state.queue.filter(a=>a.status==='serving').length,'↗','Currently in service')}</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Today’s live queue</div><div class="panel-subtitle">Priority assistance is shown first, then appointment time.</div></div><div class="table-tools"><input class="search-input" id="table-search" placeholder="Search name or token…" value="${escapeHTML(state.search)}"><select class="filter-select" id="status-filter"><option value="all">All active</option>${['booked','waiting','checked_in','serving'].map(s=>`<option value="${s}" ${state.filter===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr><th>TOKEN</th><th>CITIZEN</th><th>SERVICE / BRANCH</th><th>APPOINTMENT</th><th>PRIORITY</th><th>STATUS</th><th>EST.</th><th>NEXT ACTION</th></tr></thead><tbody>${list.length?list.map(a=>`<tr><td class="token-cell">${escapeHTML(a.token)}</td><td><b>${escapeHTML(a.user_name)}</b><br><span style="font-size:9px;color:#9aa79f">${escapeHTML(a.phone||'')}</span></td><td><b>${escapeHTML(a.service)}</b><br><span style="font-size:9px;color:#98a69d">${escapeHTML(a.branch_name)}</span></td><td>${escapeHTML(a.slot)}<br><span style="font-size:9px;color:#98a69d">${prettyDate(a.appointment_date)}</span></td><td><span class="pill">${a.priority==='normal'?'Standard':'✧ '+statusLabel(a.priority)}</span></td><td>${statusBadge(a.status)}</td><td>${a.estimated_minutes} min</td><td><select class="filter-select queue-status" data-queue-id="${a.id}" aria-label="Update ${a.token} status"><option value="">Update…</option>${['waiting','serving','completed','no_show'].map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></td></tr>`).join(''):`<tr><td colspan="8" class="table-empty">No active queue entries for today.</td></tr>`}</tbody></table></div></section><p style="font-size:10px;color:#9aa79f;margin:13px 2px">Queue order uses the appointment time and declared priority category. Staff should apply priority policy fairly and consistently.</p>`;}
function renderLiveQueue(){return `${pageHead('PUBLIC QUEUE FEED','Live queue monitor','See what is happening at each service centre. Token IDs and statuses are public; customer names stay private.','<button class="btn btn-light" data-action="refresh-live">↻ Refresh now</button>')}<div class="stat-grid" id="live-queue-stats"><div class="panel" style="padding:18px">Loading live queue…</div></div><section class="panel" style="margin-bottom:18px"><div class="panel-head"><div><div class="panel-title">Queue activity</div><div class="panel-subtitle">Automatically refreshes every 10 seconds · demo seed records are clearly labelled</div></div><span class="pill"><i></i> LIVE FEED</span></div><div id="live-queue-content">Loading tokens…</div><p id="live-queue-updated" style="font-size:10px;color:#91a096;margin:14px 0 0">Connecting to queue feed…</p></section><p class="field-help">Wait estimates are predictions from seeded historical service times and current queue load. They are not guaranteed. This demo feed updates from the database; it is not connected to a real government queue.</p>`;}
function renderBranches(){const citizen=state.user.role==='citizen';const sorted=[...state.branches].sort((a,b)=>(a.estimated_wait_minutes||a.active_queue*12||0)-(b.estimated_wait_minutes||b.active_queue*12||0));return `${pageHead('SERVICE NETWORK','Nearby branch recommendations','Compare estimated wait, queue size and available demo slots. Pick a branch with a shorter predicted wait.',state.user.role==='admin'?'<button class="btn btn-primary" data-action="add-branch">＋ Add branch</button>':'')}<section class="panel" style="padding:12px;margin-bottom:18px"><div class="panel-head"><div><div class="panel-title">Branch map</div><div class="panel-subtitle">OpenStreetMap tiles via Leaflet. If map tiles or location access are unavailable, use the branch cards below.</div></div></div><div id="branch-map" style="height:330px;border-radius:12px;background:#eef3ef;display:grid;place-items:center;color:#819087">Loading map…</div><div id="branch-map-fallback" class="field-help">Map pins show the seeded demo branch coordinates. Distance and live routing require a location/routing provider.</div></section><div class="stat-grid">${statCard('Available branches',state.branches.length,'⌖','Across the current demo network')}${statCard('Lowest active queue',(state.branches.length?Math.min(...state.branches.map(b=>b.active_queue||0)):0),'↘','Active records today')}${statCard('Service types',new Set(state.branches.map(b=>b.service_type)).size,'▤','Different service categories')}${statCard('Recommended branch',sorted[0]?.name||'—','✦','Lowest predicted wait')}</div><div class="lower-grid">${sorted.map((b,i)=>`<section class="panel" style="padding:20px;${i===0?'border:1px solid #b8d7c5':''}"><div style="display:flex;justify-content:space-between;gap:10px"><div class="branch-symbol" style="width:43px;height:43px;font-size:20px">⌖</div><span class="pill"><i></i> ${b.active_queue||0} in queue</span></div><h3 style="font-family:Manrope;font-size:16px;letter-spacing:-.3px;margin:17px 0 7px">${escapeHTML(b.name)} ${i===0?'<span class="pill">Recommended</span>':''}</h3><p style="font-size:11px;color:#8a9b90;line-height:1.6;margin:0 0 16px">${escapeHTML(b.address)}, ${escapeHTML(b.city)}</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid #edf1ed;padding-top:13px"><div><small style="display:block;font-size:9px;color:#9aa79f;margin-bottom:5px">PREDICTED WAIT</small><b>${b.estimated_wait_minutes??Math.max(0,(b.active_queue||0)-1)*12} min</b></div><div><small style="display:block;font-size:9px;color:#9aa79f;margin-bottom:5px">AVAILABLE SLOTS</small><b>${b.available_slots??Math.max(0,12-(b.active_queue||0))}</b></div></div><div style="border-top:1px solid #edf1ed;padding-top:13px;margin-top:12px;display:flex;justify-content:space-between;align-items:center"><div><small style="display:block;font-size:9px;color:#9aa79f;margin-bottom:5px">SERVICE CATEGORY</small><b style="font-size:10px">${escapeHTML(b.service_type)}</b></div>${citizen?`<button class="btn btn-primary btn-small" data-book-branch="${b.id}">Book here →</button>`:''}</div></section>`).join('')}</div><p style="font-size:10px;color:#9aa79f;margin:18px 0 0">Recommendation ranking uses predicted wait and available demo slots. Distance is not ranked until a user location or routing service is available; no fake distance is displayed.</p>`;}
async function refreshLiveQueue(){const host=$('#live-queue-content');if(!host)return;try{const d=await fetch('/api/public/live-queue?date='+encodeURIComponent(today()),{cache:'no-store'}).then(r=>r.json());const q=d.queue||[];const serving=q.filter(x=>x.status==='serving').length,waiting=q.filter(x=>['waiting','checked_in','booked'].includes(x.status)).length;const stats=$('#live-queue-stats');if(stats)stats.innerHTML=statCard('Active tokens',q.length,'≋','Across all branches')+statCard('Currently serving',serving,'↗','Service in progress')+statCard('Waiting / booked',waiting,'◷','Awaiting service')+statCard('Branches active',new Set(q.map(x=>x.branch_id)).size,'⌖','With active tokens');host.innerHTML=q.length?`<div class="table-wrap"><table><thead><tr><th>POSITION</th><th>TOKEN</th><th>BRANCH</th><th>SERVICE</th><th>STATUS</th><th>COUNTER</th><th>PREDICTED WAIT</th></tr></thead><tbody>${q.map(x=>`<tr><td><b>#${x.queue_position}</b></td><td class="token-cell">${escapeHTML(x.token)}</td><td>${escapeHTML(x.branch_name)}</td><td>${escapeHTML(x.service)}</td><td>${statusBadge(x.status)}</td><td>${escapeHTML(x.counter_name||'To be assigned')}</td><td>${x.status==='serving'?'Serving now':x.estimated_wait_minutes+' min'}</td></tr>`).join('')}</tbody></table></div>`:'<p style="padding:22px">No active tokens for today. Try again after the demo data is seeded.</p>';const updated=$('#live-queue-updated');if(updated)updated.textContent=`Last database refresh: ${new Date(d.updated_at).toLocaleTimeString()} · Refreshes every 10 seconds · ${d.seeded_demo_data?'Includes seeded demonstration data':''}`;}catch(e){host.textContent='Live feed temporarily unavailable. Refresh to retry.';}}
async function initBranchMap(){const host=$('#branch-map');if(!host)return;try{const d=await fetch('/api/public/branches',{cache:'no-store'}).then(r=>r.json());if(!window.L){host.textContent='Map library unavailable. Use the branch comparison cards below.';return;}const valid=d.branches.filter(b=>b.latitude&&b.longitude);if(!valid.length){host.textContent='No branch coordinates configured yet. Branch cards remain available below.';return;}const map=L.map(host).setView([valid[0].latitude,valid[0].longitude],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);valid.forEach(b=>L.marker([b.latitude,b.longitude]).addTo(map).bindPopup(`<b>${escapeHTML(b.name)}</b><br>Queue: ${b.active_queue}<br>Predicted wait: ${b.estimated_wait_minutes} min<br>Slots: ${b.available_slots}`));if(valid.length>1)map.fitBounds(valid.map(b=>[b.latitude,b.longitude]),{padding:[25,25]});host._leafletMap=map;}catch(e){host.textContent='Map could not load. Use the branch cards below for working branch selection.';}}
function renderNotifications(){return `${pageHead('STAY IN THE LOOP','Notifications','Booking confirmations, queue changes and support updates in one place.',`<button class="btn btn-light" data-action="mark-read">✓ Mark all as read</button>`)}<section class="panel"><div class="panel-head"><div><div class="panel-title">Your updates</div><div class="panel-subtitle">${state.notifications.filter(n=>!n.read).length} unread notification${state.notifications.filter(n=>!n.read).length===1?'':'s'}</div></div></div><div class="notification-list">${state.notifications.length?state.notifications.map(n=>`<div class="notification ${n.read?'':'unread'}"><div class="notification-icon">${/appointment/i.test(n.title)?'◷':/complaint|ticket/i.test(n.title)?'✉':'✧'}</div><div class="notification-body"><b>${escapeHTML(n.title)}</b><p>${escapeHTML(n.message)}</p><small>${new Date(n.created_at+'Z').toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}</small></div>${n.read?'':`<span class="unread-mark"></span>`}</div>`).join(''):emptyState('♧','You’re all caught up','New updates will appear here when something changes.')}</div></section>`;}
function renderFeedback(){if(state.user.role==='citizen')return `${pageHead('YOUR VOICE MATTERS','Share feedback','A few words from you can make someone else’s visit better.')}<div class="booking-layout"><section class="panel form-panel"><form id="feedback-form"><div class="form-grid"><div class="form-field full"><label for="feedback-appointment">Which visit was this about? (optional)</label><select id="feedback-appointment" name="appointment_id"><option value="">General feedback</option>${state.appointments.filter(a=>a.user_id===state.user.id).map(a=>`<option value="${a.id}">${escapeHTML(a.token)} · ${escapeHTML(a.service)} · ${prettyDate(a.appointment_date)}</option>`).join('')}</select></div><div class="form-field full"><label for="rating">How was your experience?</label><select id="rating" name="rating" required><option value="">Choose a rating</option><option value="5">★★★★★ — Excellent</option><option value="4">★★★★☆ — Good</option><option value="3">★★★☆☆ — Okay</option><option value="2">★★☆☆☆ — Could be better</option><option value="1">★☆☆☆☆ — Poor</option></select></div><div class="form-field full"><label for="comment">Anything you’d like us to know?</label><textarea id="comment" name="comment" maxlength="1000" placeholder="Tell us what worked well or what we could improve…"></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">Send feedback →</button></div></form></section><aside class="booking-aside"><div class="aside-icon">☆</div><h3>Every voice<br>helps us improve.</h3><p>We use feedback to understand what feels smooth, where people get stuck and how service teams can improve the experience.</p><div class="aside-tip"><b>✦ Be specific</b><br>Even one detail about your wait, communication or service can help.</div></aside></div>`;return `${pageHead('CITIZEN EXPERIENCE','Feedback & ratings','Review feedback shared by citizens after their visits.')}<section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Recent feedback</div><div class="panel-subtitle">Service experience insights</div></div></div><div class="table-wrap"><table><thead><tr><th>CITIZEN</th><th>RATING</th><th>COMMENT</th><th>SUBMITTED</th></tr></thead><tbody id="feedback-rows"><tr><td colspan="4" class="table-empty">Loading feedback…</td></tr></tbody></table></div></section>`;}
function renderComplaints(){const citizen=state.user.role==='citizen';return `${pageHead('HERE TO HELP','Help & complaints',citizen?'Tell us what happened and we’ll route it to the right team.':'Review citizen support requests and update ticket status.',citizen?'<button class="btn btn-primary" data-action="new-complaint">＋ New support ticket</button>':'')}<section class="panel"><div class="panel-head"><div><div class="panel-title">${citizen?'Your support tickets':'Incoming support tickets'}</div><div class="panel-subtitle">Status and suggested routing are visible on each ticket.</div></div><span class="pill">${state.complaints.length} ticket${state.complaints.length===1?'':'s'}</span></div>${state.complaints.length?state.complaints.map(c=>`<div class="complaint-card"><div class="notification-icon">✉</div><div class="complaint-main"><h4>${escapeHTML(c.subject)} <span style="font-size:9px;color:#a0ada4;font-weight:500">#${c.id}</span></h4><p>${escapeHTML(c.message)}</p><small>${citizen?'Submitted':'From '+escapeHTML(c.user_name)} · ${escapeHTML(c.category)} · Routed to ${escapeHTML(c.suggested_team||'Support team')}</small></div><div style="display:grid;gap:8px;justify-items:end">${statusBadge(c.status)}${citizen?'':`<select class="filter-select complaint-status" data-complaint-id="${c.id}"><option value="">Update…</option>${['open','in_progress','resolved'].map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select>`}</div></div>`).join(''):emptyState('✉','No support tickets yet',citizen?'If you need help, create a ticket and we’ll route it to the right team.':'New citizen support tickets will appear here.',citizen?'<button class="btn btn-primary btn-small" data-action="new-complaint">Create a ticket →</button>':'')}</section>`;}
function renderUsers(){if(state.user.role!=='admin')return renderDashboard();return `${pageHead('ACCESS & PEOPLE','User management','Review demo accounts and assigned access roles.',`<button class="btn btn-light" data-action="refresh">↻ Refresh</button>`)}<section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Registered users</div><div class="panel-subtitle">Password hashes are never exposed in this view.</div></div><input class="search-input" id="user-search" placeholder="Search users…"></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>PHONE</th><th>JOINED</th></tr></thead><tbody id="users-rows"><tr><td colspan="5" class="table-empty">Loading users…</td></tr></tbody></table></div></section><p style="font-size:10px;color:#9aa79f;margin-top:13px">Role changes are intentionally not exposed in this demo UI. Keep administrator access limited to trusted operators.</p>`;}
function renderReports(){return `${pageHead('ADMINISTRATION','Forecast & audit','Historical demand predictions and a traceable record of administrative queue changes.',`<button class="btn btn-light" data-action="refresh">↻ Refresh</button><button class="btn btn-primary" data-action="export">↓ Export CSV</button>`)}<section class="panel"><div class="panel-head"><div><div class="panel-title">Demand forecast</div><div class="panel-subtitle">Clearly labelled forecast calculated from historical database records.</div></div></div><div id="forecast-content">Loading forecast…</div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><div><div class="panel-title">Administrative activity</div><div class="panel-subtitle">Queue overrides, priority updates and settings changes.</div></div></div><div id="audit-content">Loading audit log…</div></section>`;}
async function loadReports(){try{const [f,a]=await Promise.all([api('/admin/forecast'),api('/admin/audit')]);const fc=$('#forecast-content'),ac=$('#audit-content');if(fc)fc.innerHTML=`<div class="stat-grid">${statCard('Expected appointments',f.forecast.expected_appointments,'▥',f.forecast.date)}${statCard('Historical days',f.historical_days,'◷','Used in the model')}</div><p class="field-help">${escapeHTML(f.label)}. Method: ${escapeHTML(f.forecast.method)}.</p><div class="table-wrap"><table><thead><tr><th>DATE</th><th>APPOINTMENTS</th></tr></thead><tbody>${f.history.map(x=>`<tr><td>${escapeHTML(x.day)}</td><td>${x.demand}</td></tr>`).join('')}</tbody></table></div>`;if(ac)ac.innerHTML=a.audit.length?`<div class="table-wrap"><table><thead><tr><th>WHEN</th><th>ACTOR</th><th>ACTION</th><th>ENTITY</th><th>DETAILS</th></tr></thead><tbody>${a.audit.map(x=>`<tr><td>${escapeHTML(x.created_at)}</td><td>${escapeHTML(x.actor_name||'System')}</td><td>${escapeHTML(x.action)}</td><td>${escapeHTML(x.entity_type)} #${x.entity_id||'—'}</td><td>${escapeHTML(x.details||'')}</td></tr>`).join('')}</tbody></table></div>`:'<p>No administrative actions recorded yet.</p>';}catch(e){const fc=$('#forecast-content');if(fc)fc.textContent=e.message;}}
function bindView(){ if(state.view==='branches')initBranchMap();if(state.view==='livequeue')refreshLiveQueue(); if(!window.__stqLivePoll){window.__stqLivePoll=setInterval(()=>{if(state.token&&state.view==='livequeue')refreshLiveQueue();},10000);} $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));const booking=$('#booking-form');if(booking)booking.onsubmit=submitBooking;const checkin=$('#quick-checkin-form');if(checkin)checkin.onsubmit=async e=>{e.preventDefault();const f=new FormData(checkin);try{await api('/queue/check-in',{method:'POST',body:JSON.stringify({token:f.get('token'),branch_id:f.get('branch_id'),counter_id:f.get('counter_id')||undefined})});await loadData();renderShell();renderView();toast('Token checked in successfully.');}catch(err){toast(err.message,'error');}};const ff=$('#feedback-form');if(ff)ff.onsubmit=submitFeedback;const search=$('#table-search');if(search)search.oninput=()=>{state.search=search.value;const p=search.selectionStart;renderView();const n=$('#table-search');if(n){n.focus();n.setSelectionRange(p,p);}};const filter=$('#status-filter');if(filter)filter.onchange=()=>{state.filter=filter.value;renderView();};$$('[data-cancel]').forEach(b=>b.onclick=()=>cancelAppointment(Number(b.dataset.cancel)));$$('[data-reschedule]').forEach(b=>b.onclick=()=>openReschedule(Number(b.dataset.reschedule)));$$('[data-appointment-status]').forEach(b=>b.onclick=()=>changeAppointment(Number(b.dataset.appointmentStatus),b.dataset.nextStatus));$$('.queue-status').forEach(s=>s.onchange=()=>{if(s.value)changeAppointment(Number(s.dataset.queueId),s.value);});$$('.complaint-status').forEach(s=>s.onchange=()=>{if(s.value)changeComplaint(Number(s.dataset.complaintId),s.value);});$$('[data-book-branch]').forEach(b=>b.onclick=()=>{navigate('book');setTimeout(()=>{const x=$('#branch_id');if(x)x.value=b.dataset.bookBranch;},0);});const us=$('#user-search');if(us)loadUsers(us.value);if($('#feedback-rows'))loadFeedback();if(state.view==='reports')loadReports();}
async function handleAction(action){if(action==='book')return navigate('book');if(action==='refresh-live'){await refreshLiveQueue();toast('Live queue refreshed.');return;}if(action==='call-next'){const branchId=state.queue[0]?.branch_id||state.branches[0]?.id;if(!branchId){toast('Add or select a service branch first.','error');return;}try{const d=await api('/queue/next',{method:'POST',body:JSON.stringify({branch_id:branchId})});await loadData();renderShell();renderView();toast('Now serving '+(d.appointment?.token||'next customer')+'.');}catch(e){toast(e.message,'error')}return;}if(action==='refresh'){try{await loadData();renderShell();renderView();toast('Latest records loaded.');}catch(e){toast(e.message,'error')}return;}if(action==='export'){try{const res=await fetch(API+'/admin/export.csv',{headers:{Authorization:'Bearer '+state.token}});if(!res.ok){const d=await res.json();throw new Error(d.error||'Could not export report.');}const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='skipthequeue-report.csv';a.click();URL.revokeObjectURL(url);toast('Report downloaded.');}catch(e){toast(e.message,'error')}return;}if(action==='mark-read'){try{await Promise.all(state.notifications.filter(n=>!n.read).map(n=>api(`/notifications/${n.id}/read`,{method:'PATCH'})));await loadData();renderShell();renderView();toast('All notifications marked as read.');}catch(e){toast(e.message,'error')}return;}if(action==='new-complaint')return openComplaintModal();if(action==='add-branch')return openBranchModal();}
async function submitBooking(e){e.preventDefault();const f=new FormData(e.currentTarget);const body={branch_id:Number(f.get('branch_id')),service:f.get('service'),appointment_date:f.get('appointment_date'),slot:f.get('slot'),priority:f.get('priority'),notes:f.get('notes')};try{const d=await api('/appointments',{method:'POST',body:JSON.stringify(body)});await loadData();showTicket(d.appointment);toast('Appointment confirmed — your token is ready.');}catch(err){toast(err.message,'error');}}
function showTicket(a){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><h3>Appointment confirmed</h3><button class="modal-close" aria-label="Close">×</button></div><div class="ticket"><div class="ticket-overline">YOUR QUEUE TOKEN</div><div class="ticket-token">${escapeHTML(a.token)}</div><div class="ticket-qr" aria-label="Scannable appointment QR code"><span id="ticket-qr-loading">▦</span><img id="ticket-qr-image" alt="Scannable appointment QR code" style="display:none;width:100%;height:100%;object-fit:contain;padding:5px"></div><p>Keep this token handy and show it to the service team at check-in. The QR contains your appointment reference details.</p><div class="ticket-info"><div><small>DATE</small><b>${prettyDate(a.appointment_date)}</b></div><div><small>TIME SLOT</small><b>${escapeHTML(a.slot)}</b></div><div><small>SERVICE</small><b>${escapeHTML(a.service)}</b></div><div><small>ESTIMATED SERVICE</small><b>${a.estimated_minutes} minutes</b></div></div></div><div class="modal-actions"><button class="btn btn-light modal-close">Close</button><button class="btn btn-primary" id="ticket-view">View appointments →</button></div></div>`;document.body.append(modal);api('/appointments/'+a.id+'/qr').then(d=>{const img=modal.querySelector('#ticket-qr-image');const loading=modal.querySelector('#ticket-qr-loading');if(img&&modal.isConnected){img.src=d.data_url;img.style.display='block';if(loading)loading.style.display='none';}}).catch(()=>{const loading=modal.querySelector('#ticket-qr-loading');if(loading)loading.textContent='QR unavailable';});modal.querySelectorAll('.modal-close').forEach(b=>b.onclick=()=>modal.remove());modal.querySelector('#ticket-view').onclick=()=>{modal.remove();navigate('appointments');};modal.onclick=e=>{if(e.target===modal)modal.remove();};}
async function cancelAppointment(id){if(!confirm('Cancel this appointment?'))return;try{await api('/appointments/'+id,{method:'PATCH',body:JSON.stringify({status:'cancelled'})});await loadData();renderView();toast('Appointment cancelled.');}catch(e){toast(e.message,'error');}}
function openReschedule(id){const a=state.appointments.find(x=>x.id===id);if(!a)return;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><h3>Reschedule visit</h3><button class="modal-close">×</button></div><form id="reschedule-form"><div class="form-grid"><div class="form-field full"><label>New date</label><input type="date" name="appointment_date" min="${today()}" value="${a.appointment_date}" required></div><div class="form-field full"><label>New time</label><select name="slot">${['09:00','09:15','09:30','09:45','10:00','10:15','10:30','10:45','11:00','11:15','11:30','11:45','12:00','12:15','12:30','12:45','13:00','13:15','13:30','13:45','14:00','14:15','14:30','14:45','15:00','15:15','15:30','15:45','16:00','16:15','16:30','16:45'].map(s=>`<option ${a.slot===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="modal-actions"><button type="button" class="btn btn-light modal-close">Keep current slot</button><button class="btn btn-primary" type="submit">Save new time →</button></div></form></div>`;document.body.append(modal);modal.querySelectorAll('.modal-close').forEach(b=>b.onclick=()=>modal.remove());modal.querySelector('#reschedule-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/appointments/'+id,{method:'PATCH',body:JSON.stringify({appointment_date:f.get('appointment_date'),slot:f.get('slot')})});modal.remove();await loadData();renderView();toast('Your appointment has been rescheduled.');}catch(err){toast(err.message,'error');}};modal.onclick=e=>{if(e.target===modal)modal.remove();};}
async function changeAppointment(id,status){try{if(['staff','admin'].includes(state.user.role)){await api('/queue/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:status==='checked_in'?'waiting':status})});}else{await api('/appointments/'+id,{method:'PATCH',body:JSON.stringify({status})});}await loadData();renderShell();renderView();toast('Token status updated to '+statusLabel(status)+'.');}catch(e){toast(e.message,'error');}}
async function submitFeedback(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/feedback',{method:'POST',body:JSON.stringify({appointment_id:f.get('appointment_id')||null,rating:Number(f.get('rating')),comment:f.get('comment')})});toast('Thanks for sharing your feedback.');e.currentTarget.reset();}catch(err){toast(err.message,'error');}}
async function loadFeedback(){try{const d=await api('/feedback');const root=$('#feedback-rows');if(!root)return;root.innerHTML=d.feedback.length?d.feedback.map(f=>`<tr><td><b>${escapeHTML(f.user_name)}</b></td><td><span style="color:#d29a53">${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)}</span> <span style="font-size:9px;color:#9aa79f">${f.rating}/5</span></td><td style="max-width:420px;white-space:normal">${escapeHTML(f.comment||'—')}</td><td>${new Date(f.created_at+'Z').toLocaleDateString('en-IN')}</td></tr>`).join(''):'<tr><td colspan="4" class="table-empty">No feedback has been submitted yet.</td></tr>';}catch(e){toast(e.message,'error');}}
async function loadUsers(query=''){try{const d=await api('/admin/users');const root=$('#users-rows');if(!root)return;const users=d.users.filter(u=>[u.name,u.email,u.role,u.phone].join(' ').toLowerCase().includes(query.toLowerCase()));root.innerHTML=users.length?users.map(u=>`<tr><td><b>${escapeHTML(u.name)}</b></td><td>${escapeHTML(u.email)}</td><td><span class="pill">${roleName(u.role)}</span></td><td>${escapeHTML(u.phone||'—')}</td><td>${new Date(u.created_at+'Z').toLocaleDateString('en-IN')}</td></tr>`).join(''):'<tr><td colspan="5" class="table-empty">No users found.</td></tr>';const search=$('#user-search');if(search)search.oninput=()=>loadUsers(search.value);}catch(e){toast(e.message,'error');}}
function openComplaintModal(){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><h3>New support ticket</h3><button class="modal-close">×</button></div><form id="complaint-form"><div class="form-grid"><div class="form-field full"><label>Subject</label><input name="subject" maxlength="150" required placeholder="Briefly describe the issue"></div><div class="form-field full"><label>Category</label><select name="category"><option>General</option><option>Booking</option><option>Staff experience</option><option>Accessibility</option><option>Payment</option><option>Technical issue</option></select></div><div class="form-field full"><label>What happened?</label><textarea name="message" required maxlength="2000" placeholder="Share details that can help us resolve this…"></textarea><div class="field-help">A suggested team is assigned based on the words in your message. A staff member still needs to review it.</div></div></div><div class="modal-actions"><button type="button" class="btn btn-light modal-close">Cancel</button><button class="btn btn-primary" type="submit">Submit ticket →</button></div></form></div>`;document.body.append(modal);modal.querySelectorAll('.modal-close').forEach(b=>b.onclick=()=>modal.remove());modal.querySelector('#complaint-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/complaints',{method:'POST',body:JSON.stringify({subject:f.get('subject'),category:f.get('category'),message:f.get('message')})});modal.remove();await loadData();renderView();toast(`Ticket #${d.id} submitted to ${d.suggested_team}.`);}catch(err){toast(err.message,'error');}};modal.onclick=e=>{if(e.target===modal)modal.remove();};}
function openBranchModal(){const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="modal"><div class="modal-head"><h3>Add service centre</h3><button class="modal-close">×</button></div><form id="branch-form"><div class="form-grid"><div class="form-field full"><label>Branch name</label><input name="name" required></div><div class="form-field full"><label>Address</label><input name="address" required></div><div class="form-field"><label>City</label><input name="city" required value="Pune"></div><div class="form-field"><label>Service category</label><input name="service_type" required placeholder="e.g. Certificates"></div></div><div class="modal-actions"><button type="button" class="btn btn-light modal-close">Cancel</button><button class="btn btn-primary" type="submit">Add branch →</button></div></form></div>`;document.body.append(modal);modal.querySelectorAll('.modal-close').forEach(b=>b.onclick=()=>modal.remove());modal.querySelector('#branch-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/admin/branches',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});modal.remove();await loadData();renderView();toast('Branch added to the network.');}catch(err){toast(err.message,'error');}};}
async function changeComplaint(id,status){try{await api('/complaints/'+id,{method:'PATCH',body:JSON.stringify({status})});await loadData();renderView();toast('Support ticket updated.');}catch(e){toast(e.message,'error');}}
(async()=>{if(state.token){try{const d=await api('/me');state.user=d.user;await startApp();}catch(e){logout(false);}}else renderLogin();})();
